+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.<br>
+ * By default, the layout within the configured store folder will look like:
+ * <pre><code>
+ * storeFolder
+ *   |-- stored.rules (the index file of all stored rules)
+ *   |-- 6fc2fd04-b3ab-44e0-8f78-215c66f2174a (a rule violation file named randomly by UUID and referenced from stored.rules)
+ *   |-- 2186b43a-c24c-417d-bd96-547e2dfdba1c (another rule violation file)
+ *   |-- ... (more rule violation files for every rule that has been stored so far)
+ * </code></pre>
+ * To adjust the strategy how the individual rule violation files are named use the constructor
+ * {@link TextFileBasedViolationStore#TextFileBasedViolationStore(RuleViolationFileNameStrategy) TextFileBasedViolationStore(RuleViolationFileNameStrategy)}.<br>
+ * This {@link ViolationStore} can be configured through the following properties:
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=...          # random, description, or a RuleViolationFileNameStrategy class
+ * default.integrity=...          # ignore, repair, or fail
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_DEFAULT = "ignore";
+
+    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();
+    private static final ConcurrentHashMap<String, Object> STORE_LOCKS_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean hasConstructorStrategy;
+
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private boolean fileNamesAreDerived;
+    private IntegrityMode integrityMode;
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private FileSyncedProperties storedRules;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s
+     *
+     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+        hasConstructorStrategy = false;
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        constructorStrategy = checkNotNull(ruleViolationFileNameStrategy);
+        hasConstructorStrategy = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        checkNotNull(properties);
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = IntegrityMode.parse(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s.%s=true",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        configureFileNameStrategy(properties);
+        String path = properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
+        storeFolder = new File(path);
+        File storedRulesFile = getStoredRulesFile();
+        String canonicalPath = canonicalPathOf(storedRulesFile);
+        Object lock = STORE_LOCKS_BY_PATH.computeIfAbsent(canonicalPath, ignored -> new Object());
+
+        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());
+        synchronized (lock) {
+            initializeLocked(storedRulesFile, canonicalPath);
+        }
+    }
+
+    private void configureFileNameStrategy(Properties properties) {
+        if (hasConstructorStrategy) {
+            if (properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Cannot configure %s when a file name strategy was supplied to the constructor",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            ruleViolationFileNameStrategy = constructorStrategy;
+            fileNamesAreDerived = true;
+            return;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (configured == null || configured.equals("random")) {
+            ruleViolationFileNameStrategy = ignored -> UUID.randomUUID().toString();
+            fileNamesAreDerived = false;
+        } else if (configured.equals("description")) {
+            ruleViolationFileNameStrategy = TextFileBasedViolationStore::createDescriptionFileName;
+            fileNamesAreDerived = true;
+        } else {
+            ruleViolationFileNameStrategy = instantiateStrategy(configured);
+            fileNamesAreDerived = true;
+        }
+    }
+
+    @SuppressWarnings("unchecked")
+    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
+        try {
+            Class<?> strategyType = Class.forName(className);
+            Constructor<?> constructor = strategyType.getConstructor();
+            Object strategy = constructor.newInstance();
+            checkArgument(strategy instanceof RuleViolationFileNameStrategy,
+                    "Configured file name strategy %s does not implement %s", className, RuleViolationFileNameStrategy.class.getName());
+            return (RuleViolationFileNameStrategy) strategy;
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | SecurityException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s of configured type '%s=%s' (the type must have a public no-argument constructor)",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, className), e);
+        }
+    }
+
+    private void initializeLocked(File storedRulesFile, String canonicalPath) {
+        Path folderPath = storeFolder.toPath();
+        Path indexPath = storedRulesFile.toPath();
+        boolean indexExists = pathExists(indexPath);
+
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        ensureFolder(folderPath);
+        if (indexExists && !isRegularFileWithoutFollowingLinks(indexPath)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "The stored rules index must be a regular file directly in the store folder: %s", indexPath));
+        }
+
+        FileSyncedProperties rules = getOrCreateStoredRules(canonicalPath, storedRulesFile);
+        rules.reload(indexExists);
+
+        IntegrityReport report = integrityMode == IntegrityMode.IGNORE
+                ? IntegrityReport.empty()
+                : inspect(folderPath, indexPath, rules.snapshot());
+
+        if (integrityMode == IntegrityMode.FAIL && report.hasIssues()) {
+            throw new StoreInitializationFailedException(report.message(folderPath));
+        }
+
+        boolean changed = integrityMode == IntegrityMode.REPAIR && repair(report, rules, folderPath, indexPath);
+        if (!indexExists) {
+            rules.createFile();
+        }
+        if (changed) {
+            rules.syncFileSystem();
+        }
+        storedRules = rules;
+    }
+
+    private FileSyncedProperties getOrCreateStoredRules(String canonicalPath, File storedRulesFile) {
+        return STORED_RULES_BY_PATH.computeIfAbsent(canonicalPath, ignored -> new FileSyncedProperties(storedRulesFile));
+    }
+
+    private File getStoredRulesFile() {
+        return new File(storeFolder, STORED_RULES_FILE_NAME);
+    }
+
+    private void ensureFolder(Path folderPath) {
+        try {
+            if (Files.isDirectory(folderPath)) {
+                return;
+            }
+            if (pathExists(folderPath)) {
+                throw new StoreInitializationFailedException(String.format("Store path is not a directory: %s", folderPath));
+            }
+            Files.createDirectories(folderPath);
+            if (!Files.isDirectory(folderPath)) {
+                throw new StoreInitializationFailedException(String.format("Cannot create store directory: %s", folderPath));
+            }
+        } catch (IOException | SecurityException e) {
+            throw new StoreInitializationFailedException(String.format("Cannot create store directory: %s", folderPath), e);
+        }
+    }
+
+    private String canonicalPathOf(File file) {
+        try {
+            return file.getCanonicalPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storedRules) {
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        synchronized (storedRules) {
+            String normalizedDescription = ensureUnixLineBreaks(rule.getDescription());
+            String existingFileName = storedRules.getProperty(rule.getDescription());
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                if (existingFileName == null) {
+                    return;
+                }
+                forgetKnownRule(normalizedDescription, existingFileName);
+                return;
+            }
+
+            String fileName = existingFileName != null ? existingFileName : createRequiredFileName(rule.getDescription());
+            Path target = validateSaveTarget(fileName, existingFileName != null);
+            boolean newEntry = existingFileName == null;
+            try {
+                write(violations, target);
+                if (newEntry) {
+                    storedRules.put(normalizedDescription, fileName);
+                    try {
+                        storedRules.syncFileSystem();
+                    } catch (RuntimeException e) {
+                        storedRules.remove(normalizedDescription);
+                        deletePathIfPossible(target);
+                        throw e;
+                    }
+                }
+            } catch (StoreUpdateFailedException e) {
+                throw e;
+            } catch (RuntimeException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+    }
+
+    private String createRequiredFileName(String description) {
+        String fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (fileName == null || fileName.isEmpty()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "The rule violation file name strategy returned no name for rule '%s'", description));
+        }
+        return fileName;
+    }
+
+    private Path validateSaveTarget(String fileName, boolean existingEntry) {
+        Path target = resolveDirectPath(fileName);
+        if (target == null) {
+            throw new StoreUpdateFailedException(String.format("Invalid rule violation file name: %s", fileName));
+        }
+        if (sameFileAsIndex(target)) {
+            throw new StoreUpdateFailedException(String.format("Rule violation file name leads to the stored rules index: %s", fileName));
+        }
+        if (!existingEntry && (pathExists(target) || storedRules.containsFileName(fileName))) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Rule violation file name is already in use: %s", fileName));
+        }
+
+        if (pathExists(target)) {
+            ResolvedFile resolved = resolveFile(target);
+            if (resolved == null || !resolved.regular || !resolved.direct) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Rule violation file name does not lead directly into the store folder: %s", fileName));
+            }
+        }
+        return target;
+    }
+
+    private void forgetKnownRule(String normalizedDescription, String fileName) {
+        if (!isSharedFile(normalizedDescription, fileName)) {
+            Path target = resolveDirectPath(fileName);
+            if (target != null && !sameFileAsIndex(target)) {
+                deleteNamedFile(target);
+            } else if (target != null && sameFileAsIndex(target)) {
+                throw new StoreUpdateFailedException("Cannot remove a rule violation file that is the stored rules index");
+            }
+        }
+        storedRules.remove(normalizedDescription);
+        storedRules.syncFileSystem();
+    }
+
+    private boolean isSharedFile(String keyToIgnore, String fileName) {
+        Map<String, String> entries = storedRules.snapshot().stringPropertyNames().stream()
+                .collect(Collectors.toMap(key -> key, storedRules::getProperty, (left, right) -> left, LinkedHashMap::new));
+        ResolvedFile file = resolveFile(resolveDirectPath(fileName));
+        for (Map.Entry<String, String> entry : entries.entrySet()) {
+            if (entry.getKey().equals(keyToIgnore)) {
+                continue;
+            }
+            if (entry.getValue().equals(fileName)) {
+                return true;
+            }
+            ResolvedFile other = resolveFile(resolveDirectPath(entry.getValue()));
+            if (file != null && other != null && file.identity.equals(other.identity)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetails, builder.toString().getBytes(UTF_8), StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING,
+                    StandardOpenOption.WRITE);
+        } catch (IOException | InvalidPathException | SecurityException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storedRules) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            String result = new String(toByteArray(new File(storeFolder, fileName)), UTF_8);
+            return ensureUnixLineBreaks(result);
+        } catch (IOException | InvalidPathException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private IntegrityReport inspect(Path folderPath, Path indexPath, Properties properties) {
+        Path realFolder = realPath(folderPath);
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String fileName = properties.getProperty(description);
+            String derivedName = fileNamesAreDerived ? createRequiredFileName(description) : null;
+            ResolvedFile resolved = resolveFile(folderPath, fileName);
+            boolean pointsToIndex = resolved != null && sameFile(resolved, indexPath);
+            boolean broken = resolved == null || !resolved.regular || !resolved.direct || pointsToIndex;
+            boolean resolvedWithoutViolations = !broken && containsNoViolations(resolved.realPath);
+            boolean misplaced = derivedName != null && !fileName.equals(derivedName);
+            entries.add(new Entry(description, fileName, derivedName, resolved, broken, resolvedWithoutViolations, misplaced));
+        }
+
+        Map<String, List<Entry>> entriesByName = new HashMap<>();
+        Map<String, List<Entry>> entriesByFile = new HashMap<>();
+        for (Entry entry : entries) {
+            entriesByName.computeIfAbsent(entry.fileName, ignored -> new ArrayList<>()).add(entry);
+            if (entry.resolved != null) {
+                entriesByFile.computeIfAbsent(entry.resolved.identity, ignored -> new ArrayList<>()).add(entry);
+            }
+        }
+        for (Entry entry : entries) {
+            entry.shared = entriesByName.get(entry.fileName).size() > 1
+                    || (entry.resolved != null && entriesByFile.get(entry.resolved.identity).size() > 1);
+            entry.colliding = entry.derivedName != null && entries.stream()
+                    .anyMatch(other -> other != entry && entry.derivedName.equals(other.derivedName));
+            entry.occupied = entry.misplaced && isOccupied(entry, folderPath, properties);
+        }
+
+        List<String> unownedFiles = findUnownedFiles(folderPath, indexPath, entries);
+        return new IntegrityReport(entries, unownedFiles, realFolder);
+    }
+
+    private boolean isOccupied(Entry entry, Path folderPath, Properties properties) {
+        Path derivedPath = resolveDirectPath(folderPath, entry.derivedName);
+        if (derivedPath == null || !isDirectPath(derivedPath, folderPath)) {
+            return true;
+        }
+        if (pathExists(derivedPath)) {
+            return true;
+        }
+        for (String otherDescription : properties.stringPropertyNames()) {
+            if (!otherDescription.equals(entry.description) && entry.derivedName.equals(properties.getProperty(otherDescription))) {
+                return true;
+            }
+        }
+        return false;
+    }
