    private boolean repair(IntegrityReport report, FileSyncedProperties rules, Path folderPath, Path indexPath) {
        boolean changed = false;
        for (Entry entry : report.entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken || entry.resolvedWithoutViolations) {
                if (!entry.broken && entry.resolved != null && entry.resolved.regular && !sameFile(entry.resolved, indexPath)) {
                    try {
                        deleteNamedFile(entry.resolved.path);
                    } catch (StoreUpdateFailedException e) {
                        throw new StoreInitializationFailedException(e);
                    }
                }
                rules.remove(entry.description);
                changed = true;
            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
                Path destination = resolveDirectPath(folderPath, entry.derivedName);
                if (destination == null) {
                    throw new StoreInitializationFailedException("Cannot derive a valid rule violation file name");
                }
                try {
                    Path source = Files.isSymbolicLink(entry.resolved.path) ? entry.resolved.realPath : entry.resolved.path;
                    Files.move(source, destination);
                } catch (IOException | SecurityException e) {
                    throw new StoreInitializationFailedException(String.format(
                            "Cannot move rule violation file '%s' to '%s'", entry.fileName, entry.derivedName), e);
                }
                rules.put(entry.description, entry.derivedName);
                changed = true;
            }
        }
        return changed;
    }

    private void deleteNamedFile(Path path) {
        if (path == null || !pathExists(path)) {
            return;
        }
        try {
            if (Files.isSymbolicLink(path)) {
                Path target;
                try {
                    target = path.toRealPath();
                } catch (IOException e) {
                    Files.deleteIfExists(path);
                    return;
                }
                if (Files.isRegularFile(target)) {
                    Files.deleteIfExists(target);
                }
                Files.deleteIfExists(path);
            } else if (Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS)) {
                Files.deleteIfExists(path);
            } else {
                throw new IOException("not a regular file");
            }
        } catch (IOException | SecurityException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private void deletePathIfPossible(Path path) {
        try {
            if (path != null && pathExists(path) && !Files.isSymbolicLink(path)) {
                Files.deleteIfExists(path);
            }
        } catch (IOException | SecurityException ignored) {
            // The original update exception is more useful to the caller.
        }
    }

    private Path resolveDirectPath(String fileName) {
        return resolveDirectPath(storeFolder.toPath(), fileName);
    }

    private Path resolveDirectPath(Path folderPath, String fileName) {
        try {
            Path folder = folderPath.toAbsolutePath().normalize();
            Path result = folder.resolve(fileName).normalize();
            return isDirectPath(result, folder) ? result : null;
        } catch (InvalidPathException | NullPointerException e) {
            return null;
        }
    }

    private boolean isDirectPath(Path path, Path folderPath) {
        Path folder = folderPath.toAbsolutePath().normalize();
        return path.getParent() != null && folder.equals(path.getParent().toAbsolutePath().normalize());
    }

    private ResolvedFile resolveFile(Path folderPath, String fileName) {
        Path path = resolveDirectPath(folderPath, fileName);
        return resolveFile(path, folderPath);
    }

    private ResolvedFile resolveFile(Path path) {
        return resolveFile(path, storeFolder.toPath());
    }

    private ResolvedFile resolveFile(Path path, Path folderPath) {
        if (path == null || !pathExists(path)) {
            return null;
        }
        try {
            Path realPath = path.toRealPath();
            BasicFileAttributes attributes = Files.readAttributes(realPath, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
            return new ResolvedFile(path, realPath, attributes.isRegularFile(), identityOf(attributes, realPath),
                    realPath.getParent() != null && realPath.getParent().equals(realPath(folderPath)));
        } catch (IOException | SecurityException e) {
            return null;
        }
    }

    private Path realPath(Path path) {
        try {
            return path.toRealPath();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private boolean containsNoViolations(Path file) {
        try {
            byte[] bytes = Files.readAllBytes(file);
            for (byte value : bytes) {
                if (value != '\n' && value != '\r') {
                    return false;
                }
            }
            return true;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private boolean sameFileAsIndex(Path path) {
        if (path == null) {
            return false;
        }
        try {
            return samePath(path, new File(storeFolder, STORED_RULES_FILE_NAME).toPath())
                    || (pathExists(path) && pathExists(new File(storeFolder, STORED_RULES_FILE_NAME).toPath())
                    && Files.isSameFile(path, new File(storeFolder, STORED_RULES_FILE_NAME).toPath()));
        } catch (IOException | SecurityException e) {
            return false;
        }
    }

    private boolean sameFile(ResolvedFile file, Path other) {
        try {
            if (!pathExists(other)) {
                return false;
            }
            BasicFileAttributes otherAttributes = Files.readAttributes(other, BasicFileAttributes.class);
            return file.identity.equals(identityOf(otherAttributes, other.toRealPath()));
        } catch (IOException | SecurityException e) {
            return false;
        }
    }

    private boolean samePath(Path left, Path right) {
        return left.toAbsolutePath().normalize().equals(right.toAbsolutePath().normalize());
    }

    private String identityOf(Path path) throws IOException {
        BasicFileAttributes attributes = Files.readAttributes(path, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
        return identityOf(attributes, path.toRealPath());
    }

    private String identityOf(BasicFileAttributes attributes, Path path) {
        Object fileKey = attributes.fileKey();
        return fileKey == null ? "path:" + path.toAbsolutePath().normalize() : "key:" + fileKey;
    }

    private static String createDescriptionFileName(String description) {
        String normalizedDescription = ensureUnixLineBreaks(description);
        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(normalizedDescription);
        String keptWord = null;
        while (matcher.find()) {
            keptWord = matcher.group(1);
        }
        String hash = sha256(normalizedDescription);
        String prefix = keptWord == null ? "rule" : keptWord;
        return prefix + "-" + hash;
    }

    private static String sha256(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
            StringBuilder result = new StringBuilder(digest.length * 2);
            for (byte current : digest) {
                result.append(String.format("%02x", current & 0xff));
            }
            return result.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private static boolean pathExists(Path path) {
        return path != null && (Files.exists(path, LinkOption.NOFOLLOW_LINKS) || Files.isSymbolicLink(path));
    }

    private static boolean isRegularFileWithoutFollowingLinks(Path path) {
        return Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS);
    }

    private static class FileSyncedProperties {
        private final File propertiesFile;
        private Properties loadedProperties = new Properties();

        FileSyncedProperties(File file) {
            propertiesFile = file;
        }

        void reload(boolean fileExists) {
            loadedProperties = fileExists ? loadRulesFrom(propertiesFile) : new Properties();
        }

        Properties snapshot() {
            Properties result = new Properties();
            result.putAll(loadedProperties);
            return result;
        }

        boolean containsKey(String propertyName) {
            return loadedProperties.containsKey(ensureUnixLineBreaks(propertyName));
        }

        String getProperty(String propertyName) {
            return loadedProperties.getProperty(ensureUnixLineBreaks(propertyName));
        }

        boolean containsFileName(String fileName) {
            for (String value : loadedProperties.stringPropertyNames()) {
                if (fileName.equals(loadedProperties.getProperty(value))) {
                    return true;
                }
            }
            return false;
        }

        void put(String key, String value) {
            loadedProperties.setProperty(ensureUnixLineBreaks(key), value);
        }

        void remove(String key) {
            loadedProperties.remove(key);
        }

        void createFile() {
            try {
                if (!propertiesFile.exists() && !propertiesFile.createNewFile()) {
                    throw new IOException("Could not create index file");
                }
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
            }
        }

        private Properties loadRulesFrom(File file) {
            Properties result = new Properties();
            try (FileInputStream inputStream = new FileInputStream(file)) {
                result.load(inputStream);
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
            }
            return result;
        }

        void syncFileSystem() {
            try (FileOutputStream outputStream = new FileOutputStream(propertiesFile)) {
                loadedProperties.store(outputStream, "");
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }
    }

    private static class ResolvedFile {
        private final Path path;
        private final Path realPath;
        private final boolean regular;
        private final String identity;
        private final boolean direct;

        private ResolvedFile(Path path, Path realPath, boolean regular, String identity, boolean direct) {
            this.path = path;
            this.realPath = realPath;
            this.regular = regular;
            this.identity = identity;
            this.direct = direct;
        }
    }

    private static class Entry {
        private final String description;
        private final String fileName;
        private final String derivedName;
        private final ResolvedFile resolved;
        private final boolean broken;
        private final boolean resolvedWithoutViolations;
        private final boolean misplaced;
        private boolean shared;
